// Generated by hecks site site_projection.project_site. Do not edit.

// An approximate preview a record, drawn by the editor itself. The site refuses to be framed (it
// sends X-Frame-Options: DENY), and a draft is not on the site to be framed anyway, so this shows
// what a person has typed, before it is saved, laid out like a page: the title, the picture, the
// moments and the text, then every other value in a list. Rich text is made by the site's own
// reader and renderer, in the browser (see browser/markdown.js, `renderAll`), so it cannot differ
// from the page. The layout is the editor's and is said to be approximate on the page itself,
// with a link to the record on the live site.
import { EDITOR } from "../config.ts";
import { at } from "../names.ts";
import type { Aggregate, Attr } from "../schema.ts";
import { esc, href, statusBadge } from "./html.ts";
import { isMoment } from "./moments.ts";
import { titleOf } from "./paging.ts";
import { plainText } from "./links.ts";
import { previewUrl } from "./preview.ts";
import { page } from "./shell.ts";
import { keyOf } from "../names.ts";
import { valueOf, valueRows } from "./values.ts";
import { label, nameOf } from "./words.ts";

type State = Record<string, unknown>;

/** One text of the record that is written on its form (a description, a body): its words and what was typed. */
export interface PreviewText {
  label: string;
  value: string;
}

/** Whether a value says anything. */
const held = (value: unknown): boolean => value !== undefined && value !== null && value !== "" && !(Array.isArray(value) && value.length === 0) && plainText(value) !== "" || (Array.isArray(value) && value.length > 0);

/**
 * The page. `id` is the record's address when it exists, null for one that is being made; `leave`
 * is where "Back to the form" goes (the form itself is in the tab that opened this one).
 */
export function approximatePage(agg: Aggregate, id: string | null, values: State, texts: PreviewText[]): string {
  const titleAttr = titleOf(agg);
  const heading = titleAttr ? plainText(values[titleAttr]) : "";
  const status = agg.lifecycle ? statusBadge(agg, values[agg.lifecycle.field] ?? agg.lifecycle.default) : "";
  const picture = agg.attributes.find((attr) => attr.upload?.accept === "image" && held(values[attr.name]));
  const image = picture ? `<img class="mb-4 max-h-80 w-full border border-base-300 object-cover" src="${esc(plainText(values[picture.name]))}" alt="">` : "";
  const moments = agg.attributes.filter((attr) => !attr.list && (isMoment(attr) || attr.wall !== undefined) && held(values[attr.name]));
  const when = moments.map((attr) => `<p><span class="text-muted">${esc(attr.label ?? label(attr.name))}:</span> ${valueOf(agg, attr, values)}</p>`).join("");
  const lead = agg.attributes.filter((attr) => attr.multiline && !attr.markdown && !attr.list && held(values[attr.name]));
  const intro = lead.map((attr) => `<p class="max-w-prose whitespace-pre-line">${esc(plainText(values[attr.name]))}</p>`).join("");
  const body = texts
    .filter((text) => text.value.trim() !== "")
    .map((text) => `<section class="mt-6"><h2 class="mb-2 text-sm text-muted">${esc(text.label)}</h2><div class="prose max-w-prose" data-md-render data-md="${esc(text.value)}"></div></section>`)
    .join("");
  const shownNames = new Set([titleAttr, picture?.name, ...moments.map((attr) => attr.name), ...lead.map((attr) => attr.name), agg.identity, agg.lifecycle?.field]);
  const rest = agg.attributes.filter((attr): attr is Attr => !shownNames.has(attr.name) && attr.widget !== "body" && held(values[attr.name]));
  const live = id ? previewUrl(agg, id) : null;
  const liveLink = live ? `<a class="link" href="${esc(live)}" target="_blank" rel="noopener">View on the live site</a>` : "";
  const note = `<div class="alert alert-warning alert-soft mb-6 items-start" role="note"><div><p class="font-semibold">Preview (approximate)</p><p class="text-sm">This is the editor's own drawing of what you typed, before it is saved. The site may lay it out differently, and nothing here is saved or published. ${liveLink ? `${liveLink} to see what is there now.` : "It is not on the site yet."}</p></div></div>`;
  const main = `${note}
<article class="max-w-3xl border border-base-300 bg-base-100 p-4 sm:p-8" aria-label="Preview (approximate)">
<p class="text-sm text-muted">${esc(label(nameOf(agg)))}${id ? ` · ${esc(id)}` : " · not saved yet"}</p>
<h1 class="mt-1 break-words text-3xl">${esc(heading || "Untitled")}</h1>
<p class="mt-2">${status}</p>
<div class="mt-4">${image}</div>
<div class="grid gap-1">${when}</div>
<div class="mt-4 grid gap-3">${intro}</div>
${body}
${rest.length > 0 ? `<section class="mt-8"><h2 class="mb-2 text-lg">Everything else</h2>${valueRows(agg, rest, values)}</section>` : ""}
</article>
<p class="mt-4"><button type="button" class="btn" data-close-tab>Close this preview</button></p>`;
  return page(`Preview (approximate): ${heading || nameOf(agg)}`, main, { active: keyOf(agg), crumbs: [["Home", href()], [label(nameOf(agg)), href(...at(agg))], ["Preview (approximate)"]] });
}

/** The label the form's button wears. */
export const PREVIEW_BUTTON = "Preview (approximate)";

/** Where a form posts to be previewed without saving: beside the form's own address. */
export function previewAction(action: string, creates: boolean): string {
  return creates ? `${action}/preview` : action.replace(/\/[^/]+$/, "/preview");
}

/** Whether the editor shows its own preview for this aggregate: the same records the site has a page for. */
export const previewable = (agg: Aggregate): boolean => EDITOR.preview !== null || agg.words?.preview !== undefined;
